#!/usr/bin/env node
/* scope-report.js (gated-fix-plan): READ-ONLY facts for the scope analysis an executor must do before running a plan.
 *
 *   node fix-plan/scope-report.js [projectRoot]
 *
 * Prints, from the files as they are now (never from memory):
 *  1. the scope: every edited / generated file, its size, lines, line endings, and whether it still matches the baseline;
 *  2. every edit: which file, which plan goals it serves, where its `find` text sits now (line numbers, how many times),
 *     the surrounding code, and whether the replacement is already present (plan already applied?);
 *  3. what protects each edit: the mutations on the same file and the tests they must make fail;
 *  4. what must not change: invariants (with their current line span) and the count of out-of-scope files;
 *  5. a verdict line: READY / ALREADY APPLIED / MISMATCH, with the reasons.
 * Writes nothing.
 */
'use strict';
const fs = require('fs'), path = require('path');
const L = require('./lib.js');
const HERE = __dirname;
const root = path.resolve(process.argv[2] || '.');
const C = require(path.join(HERE, 'config.js'));
const EDITS = require(path.join(HERE, 'edits.js'));
const E = fs.existsSync(path.join(HERE, 'expected.json')) ? JSON.parse(fs.readFileSync(path.join(HERE, 'expected.json'), 'utf8')) : null;
const CR = String.fromCharCode(13), LF = String.fromCharCode(10);
const issues = [];
const read = f => { const p = path.join(root, f); return fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null; };
const fixEol = (text, t) => { const eol = text.includes(CR + LF) ? CR + LF : LF; return t.split(CR + LF).join(LF).split(LF).join(eol); };
const lineAt = (text, idx) => text.slice(0, idx).split(/\r?\n/).length;
const positions = (text, needle) => { const out = []; let i = text.indexOf(needle); while (i >= 0) { out.push(lineAt(text, i)); i = text.indexOf(needle, i + 1); } return out; };

console.log(`SCOPE REPORT  root=${root}\n`);

console.log('1. SCOPE (the only files the plan may change)');
for (const [tier, files] of [['edited', C.edited], ['generated', C.generated || []]]) {
  for (const f of files) {
    const t = read(f);
    if (t === null) { issues.push(`${f} does not exist`); console.log(`  [${tier}] ${f}: MISSING`); continue; }
    const h = L.sha(fs.readFileSync(path.join(root, f)));
    const state = !E ? 'no expected.json' : h === E.baselineManifest[f] ? 'matches the planned BASELINE' : h === E.afterManifest[f] ? 'matches the planned RESULT' : 'matches NEITHER baseline nor result';
    if (E && state.startsWith('matches NEITHER')) issues.push(`${f} has drifted from both the baseline and the planned result`);
    console.log(`  [${tier}] ${f}: ${t.length} chars, ${t.split(/\r?\n/).length} lines, ${L.eolOf(t)}; ${state}`);
  }
}
if (C.generate) console.log(`  generated by: ${[C.generate.cmd, ...(C.generate.args || [])].join(' ')}`);
if (E) console.log(`  out of scope: ${Object.keys(E.baselineManifest).length - (E.changed || []).length} files must stay byte-identical`);

console.log('\n2. EDITS (what the plan will do, located in the current code)');
let applied = 0, pending = 0;
for (const e of EDITS) {
  const t = read(e.file);
  console.log(`\n  ${e.id}  ->  ${e.file}${e.fixes ? `   serves: ${[].concat(e.fixes).join(', ')}` : '   serves: (not linked to a plan goal)'}`);
  if (!e.fixes) issues.push(`edit "${e.id}" is not linked to a plan goal (add fixes: [...] or explain the link in the analysis)`);
  if (!C.edited.includes(e.file)) { issues.push(`edit "${e.id}" targets ${e.file}, outside config.edited`); continue; }
  if (t === null) continue;
  const find = fixEol(t, e.find), repl = fixEol(t, e.replace);
  const fpos = positions(t, find), rpos = repl.length ? positions(t, repl) : [];
  /* applied = the replacement is present once. When the replacement contains the find text (an insertion that keeps
     its anchor line), the find text is naturally still there, so presence of the replacement decides. */
  const isApplied = rpos.length === 1 && (fpos.length === 0 || (repl.includes(find) && fpos.length === 1)) || (!repl.length && fpos.length === 0);
  if (isApplied) {
    applied++; console.log(`     the replacement IS present${rpos.length ? ' (line ' + rpos.join(',') + ')' : ''}: this edit looks ALREADY APPLIED`);
  } else if (fpos.length === 1 && rpos.length === 0) {
    pending++;
    const lines = t.split(/\r?\n/), at = fpos[0], span = find.split(/\r?\n/).length - (find.endsWith('\n') ? 1 : 0);
    console.log(`     find text: line ${at}${span > 1 ? `-${at + span - 1}` : ''} (exactly once). Code there now, with 2 lines of context:`);
    for (let i = Math.max(1, at - 2); i <= Math.min(lines.length, at + span + 1); i++) console.log(`       ${String(i).padStart(5)}${i >= at && i < at + span ? ' >' : '  '} ${lines[i - 1].slice(0, 150)}`);
    console.log(`     becomes: ${repl.split(/\r?\n/).filter(Boolean).length} line(s); ${e.why ? 'why: ' + e.why : '(see plan section 5)'}`);
  } else {
    issues.push(`edit "${e.id}": find text occurs ${fpos.length} times (must be exactly 1)`);
    console.log(`     find text occurs ${fpos.length} times${fpos.length ? ' at lines ' + fpos.join(',') : ''}: MISMATCH`);
  }
  const muts = (C.mutations || []).filter(m => e.protectedBy ? [].concat(e.protectedBy).includes(m.id) : m.file === e.file);
  console.log(`     protected by: ${muts.length ? muts.map(m => `${m.id} (${m.what})`).join('; ') : 'no mutation listed (say in the analysis what proves this edit)'}`);
}

console.log('\n3. TESTS AND PROOF');
console.log(`  targets now failing that the plan fixes (${(C.targets || []).length}): ${(C.targets || []).join(' | ')}`);
console.log(`  must PASS afterwards: ${(C.requiredPass || []).length} tests; obsolete names that must disappear: ${(C.obsoleteNames || []).length}`);
console.log(`  unrelated failures left alone (${(C.unrelatedFails || []).length}): ${(C.unrelatedFails || []).join(' | ') || 'none'}`);
for (const m of C.mutations || []) console.log(`  mutation ${m.id} on ${m.file}: ${m.what} -> must make FAIL: ${m.mustFail.join(' | ')}`);
if (E) console.log(`  recorded tallies: before ${E.testBefore.pass} PASS / ${E.testBefore.fail} FAIL -> after ${E.testAfter.pass} PASS / ${E.testAfter.fail} FAIL`);

console.log('\n4. MUST NOT CHANGE');
for (const inv of C.invariants || []) {
  const t = read(inv.file), m = t && new RegExp(inv.regex).exec(t);
  if (!m) { issues.push(`invariant ${inv.id} not found in ${inv.file}`); console.log(`  ${inv.id}: NOT FOUND in ${inv.file}`); continue; }
  console.log(`  ${inv.id}: ${inv.desc}  (${inv.file} lines ${lineAt(t, m.index)}-${lineAt(t, m.index + m[0].length)}; ${E ? (L.invariantHash(root, inv) === E.invariants[inv.id] ? 'currently matches' : 'currently DIFFERS') : 'no expected.json'})`);
}

const verdict = issues.length ? 'MISMATCH' : applied === EDITS.length ? 'ALREADY APPLIED' : applied === 0 ? 'READY' : 'MISMATCH';
if (!issues.length && verdict === 'MISMATCH') issues.push(`half applied: ${applied} of ${EDITS.length} edits already present`);
console.log(`\nSCOPE VERDICT: ${verdict}  (${pending} edit(s) pending, ${applied} already applied)${issues.length ? '\n  - ' + issues.join('\n  - ') : ''}`);
process.exit(verdict === 'READY' ? 0 : 1);
